ids={p['id'] for p in packages};visited=set();visiting=set()
def visit(id):
 if id in visiting:raise ValueError('Cyclic dependency '+id)
 if id in visited:return
 visiting.add(id)
 for dep in next(p for p in packages if p['id']==id)['dependencies']:
  assert dep in ids,dep
  visit(dep)
 visiting.remove(id);visited.add(id)
for id in ids:visit(id)
milestone_index={m['id']:m for m in milestones};seen=set();active=set()
def check_milestone(id):
 assert id in milestone_index,id
 if id in active:raise ValueError('Cyclic milestone '+id)
 if id in seen:return
 active.add(id)
 for dep in milestone_index[id]['dependencies']:check_milestone(dep)
 active.remove(id);seen.add(id)
for id in milestone_index:check_milestone(id)
assert all('A21.complete' in milestone_index[id+'.complete']['dependencies'] for id in phased)
assert 'A17.proof_ready' in milestone_index['A21.proofs_ready']['dependencies']
